#!/usr/bin/env node
import { readRecords } from './records.mjs';
const [command, file] = process.argv.slice(2);
if (command === 'help') process.stdout.write('record-report: validate <file> | summarize <file>\n');
else if (command === 'validate') {
  try {
    const records = readRecords(file);
    process.stdout.write(`${JSON.stringify(records)}\n`);
  } catch {
    process.stderr.write('INVALID_INPUT\n');
    process.exitCode = 2;
  }
}
else { process.stderr.write('UNKNOWN_COMMAND\n'); process.exitCode = 2; }
import { readFileSync } from 'node:fs';

export function parseRecords(bytes) {
  const text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(bytes);
  if (bytes.length === 0) return [];
  const rows = (text.endsWith('\n') ? text.slice(0, -1) : text).split('\n');
  const records = [];
  const ids = new Set();
  for (const row of rows) {
    const match = /^([A-Za-z0-9_-]+),([0-9]+)$/.exec(row);
    if (!match) throw new Error('Invalid record');
    const [, id, digits] = match;
    const amount = Number(digits);
    if (!Number.isSafeInteger(amount) || ids.has(id)) throw new Error('Invalid record');
    ids.add(id);
    records.push({ id, amount });
  }
  return records;
}

export function readRecords(file) {
  return parseRecords(readFileSync(file));
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { runCli } from './test-process.mjs';
test('existing help remains stable', () => { const r=runCli(['help']); assert.equal(r.status,0); assert.equal(r.stdout,'record-report: validate <file> | summarize <file>\n'); });
import { mkdirSync, mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { join } from 'node:path';

function withInput(bytes, check) {
  mkdirSync('.tmp', { recursive: true });
  const folder = mkdtempSync(join('.tmp', 'p01-'));
  const file = join(folder, 'records');
  try {
    writeFileSync(file, bytes);
    check(file);
  } finally {
    rmSync(folder, { recursive: true, force: true });
  }
}

function assertResult(result, status, stdout, stderr) {
  assert.equal(result.status, status);
  assert.equal(result.signal, null);
  assert.equal(result.stdout, stdout);
  assert.equal(result.stderr, stderr);
}

